head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "uldmgt50009";
scwin.voidMessage = null;
scwin.attachCount = "${fn:length(byformAttaches)}";
scwin.isExpand = false;
scwin.obj = undefined;
scwin.frameId = undefined;
scwin.delAttach = null;
scwin.up = null;
scwin.down = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "img_13", attr: "src", fn: function () { return "/img/filing/body/pop_title_" + String(((String((dma_pageContext.get("mode") ?? "")) === "create") ? "33" : "34")) + ".gif"; } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        const v = a.fn();
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_editForm = { action: "", method: 'post', target: '' };

try { scwin.obj =opener.Potential.Provider; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt50009' }); }

try { scwin.frameId =scwin.obj.ActiveFrame.FrameID; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt50009' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.voidMessage = $c.util.getComponent('voidMessage');
        scwin.delAttach = delAttach;
        scwin.up = up;
        scwin.down = down;
        scwin.init_recvParam();
        scwin.init_attrReals();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'uldmgt50009.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name form_1_onsubmit
 * @description form_1 onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.form_1_onsubmit = function(e){
    try {
        return false

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50009.form_1_onsubmit' }); }
};

/**
 * @method
 * @name ipt_formKorNm_onkeyup
 * @description ipt_formKorNm 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_formKorNm_onkeyup = async function(e){
    try {
        await scwin.onEnter()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50009.ipt_formKorNm_onkeyup' }); }
};

/**
 * @method
 * @name img_53_onclick
 * @description img_53 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_53_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50009.img_53_onclick' }); }
};

/**
 * @method
 * @name attachTable_oncellclick
 * @description attachTable 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.attachTable_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_byformAttaches');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_byformAttaches */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: fn_DelAttach → removeRow (as-is 의 «남은 수 0 안내»는 미이관) */
        dl.moveRow(rowIndex, rowIndex + 1); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'attachTable.oncellclick' });
    }
};

/**
 * @method
 * @name img_94_onclick
 * @description img_94 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_94_onclick = async function(e){
    try {
        await scwin.insert()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50009.img_94_onclick' }); }
};

/**
 * @method
 * @name img_95_onclick
 * @description img_95 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_95_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50009.img_95_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Insert
 * @description Insert 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Insert = async function () {
    const sbmOptions = {
        id: "tx_fn_Insert",
        method: "post",
        action: "/filing/updateByformAttach.do",
        ref: "dma_InsertReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Search_xhr
 * @description Search xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Search_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Search_xhr", unresolved: "action:self_submit:tx_fn_Search_xhr" };
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/filing/updateByformAttach.do",
        ref: "dma_loadListReq",
        target: "dlt_byformAttaches=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    scwin.form_editForm.action = "/filing/updateByformAttach.do";
    $c.util.getComponent('dma_InsertReq').set('method', "searchFormKorNm");
    await scwin.tx_fn_Search_xhr();
};

/**
 * @method
 * @name onCompleteResponse
 * @description on Complete Response 처리
 * @param {*} responseText responseText
 * @returns {void}
 * @hidden N
 */
scwin.onCompleteResponse = function (responseText) {
    $c.util.getComponent('txt_formListDiv').setValue(responseText);
    if (!scwin.isExpand) {

    }
    scwin.isExpand = true;
};

/**
 * @method
 * @name onEnter
 * @description on Enter 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onEnter = async function () {
    if (event.keyCode === 13) {
        await scwin.search();
    }
};

/**
 * @method
 * @name selectForm
 * @description select Form 처리
 * @param {*} _index _index
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selectForm = async function (_index) {
    const formCd = $c.util.getComponent("document.all.cd_" + _index).getValue().trim();
    const formVer = $c.util.getComponent("document.all.ver_" + _index).getValue().trim();
    const formKorNm = $c.util.getComponent("document.all.nm_" + _index).getValue().trim();
    if (scwin.isExit(formCd, formVer)) {
        await $c.win.alert("이미 추가된 서식입니다.");
        return;
    }
    scwin.addAttach(formCd, formVer, formKorNm);
};

/**
 * @method
 * @name isExit
 * @description is Exit 처리
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @returns {void}
 * @hidden N
 */
scwin.isExit = function (formCd, formVer) {
    if (document.editForm.formCds === null) {
        return false;
    }
    if ($c.util.getComponent('dlt_byformAttaches').getRowCount() === null) {
        return ($c.util.getComponent("dma_InsertReq").get("formCds") === formCd && $c.util.getComponent("dma_InsertReq").get("formVers") === formVer);
    }
    for (let i = 0; i < $c.util.getComponent('dlt_byformAttaches').getRowCount(); i++) {
        if ($c.util.getComponent('dlt_byformAttaches').getCellData(i, 'formCd')=== formCd && $c.util.getComponent('dlt_byformAttaches').getCellData(i, 'formVer')=== formVer) {
            return true;
        }
    }
    return false;
};

/**
 * @method
 * @name addAttach
 * @description add Attach 처리
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @param {String} formKorNm formKorNm
 * @returns {void}
 * @hidden N
 */
scwin.addAttach = function (formCd, formVer, formKorNm) {
    const ptab = $c.util.getComponent('attachTable');
    const newAttach = ptab.insertRow();
    const formCell = newAttach.insertCell();
    formCell.className = "data_d";
    formCell.id = "attachForm";
    formCell.height = "20";
    formCell.innerHTML = "<input type=\"hidden\" name=\"formCds\" value=\"" + formCd + "\" />" + "<input type=\"hidden\" name=\"formVers\" value=\"" + formVer + "\" />" + "<input type=\"hidden\" name=\"formMandtryTpCds\" value=\"1\" />" + formKorNm;
    const buttonCell = newAttach.insertCell();
    buttonCell.width = "80";
    buttonCell.className = "btn_action";
    buttonCell.innerHTML = "<img id=\"downButton\" src=\"/img/filing/body/arrow_down2.gif\" onclick=\"down(this)\"" + " style=\"cursor:hand\" align=\"absmiddle\" />" + " <img id=\"upButton\" src=\"/img/filing/body/arrow_up2.gif\" onclick=\"up(this)\"" + " style=\"cursor:hand\" align=\"absmiddle\" />" + " <img src=\"/img/filing/btn/btn_sub.gif\" onclick=\"delAttach(this)\"" + " style=\"cursor:hand\" align=\"absmiddle\" />";
    if (scwin.attachCount > 0) {

    } else {
        scwin.voidMessage.setStyle("display", "none");
    }
    scwin.attachCount++;
};

function delAttach(obj) {
    const _tr = obj.parentNode.parentNode;
    const _tbl = _tr.parentNode;
    _tbl.removeChild(_tr);
    if (scwin.attachCount > 1) {

    } else {
        scwin.voidMessage.setStyle("display", "block");
    }
    scwin.attachCount--;
}

function up(upObj) {
    let i = 0;
    if ($c.util.getComponent('upButton') !== null) {
        if ($c.util.getComponent('upButton').length === null) {
            return;
        }
        for (i = 0; i < $c.util.getComponent('upButton').length; i++) {
            if (upObj === $c.util.getComponent('upButton')[i]) {
                break;
            }
        }
    }
    if (i === 0) {
        return;
    }
    const tempHtml = $c.util.getComponent('attachForm')[i].innerHTML;
    $c.util.getComponent('attachForm')[i].innerHTML = $c.util.getComponent('attachForm')[i - 1].innerHTML;
    $c.util.getComponent('attachForm')[i - 1].innerHTML = tempHtml;
}

function down(downObj) {
    let i = 0;
    let rowCount = 0;
    if ($c.util.getComponent('downButton') !== null) {
        if ($c.util.getComponent('downButton').length === null) {
            return;
        }
        rowCount = $c.util.getComponent('downButton').length;
        for (i = 0; i < $c.util.getComponent('downButton').length; i++) {
            if (downObj === $c.util.getComponent('downButton')[i]) {
                break;
            }
        }
    }
    if (rowCount - 1 === i) {
        return;
    }
    const tempHtml = $c.util.getComponent('attachForm')[i].innerHTML;
    $c.util.getComponent('attachForm')[i].innerHTML = $c.util.getComponent('attachForm')[i + 1].innerHTML;
    $c.util.getComponent('attachForm')[i + 1].innerHTML = tempHtml;
}

/**
 * @method
 * @name insert
 * @description insert 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.insert = async function () {
    $c.util.getComponent('dma_InsertReq').set('method', "updateByformLibrary");
    scwin.form_editForm.action = "/filing/updateByformAttach.do";
    await scwin.tx_fn_Insert();
};
